def PROJ(titre, sous, quoi, briques, competences, jalons, extension):
    """Page de projet : description, briques, compétences, et une fiche de jalons."""
    return pg(titre, sous, "feuille",
              quoi,
              (("brique", "choix suggéré"),) + tuple(briques),
              "<p><b>Ce que vous démontrez :</b> " + competences + "</p>",
              "<p><b>Pour aller plus loin :</b> " + extension + "</p>",
              fiche=F("Les jalons du projet", "du minimum viable à la version présentable", jalons))

